// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    address owner;

    function setUp() public { c = new MultiplicatorX3(); owner = address(this); }

    function testFuzz_property(uint256 value, bool calleeReverts) public {
        vm.assume(value <= 1 ether);

        address callee;
        if (calleeReverts) {
            callee = address(new Reverter());
        } else {
            callee = address(new Receiver());
        }

        vm.deal(owner, value);

        bytes memory data = "\x00";

        bool ok;
        vm.prank(owner);
        try c.Command{value: value}(callee, data) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok || value == 0);
    }
}

contract Receiver {
    receive() external payable {}
}

contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}
